head.script:
scwin.fireClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('oncontextmenu');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('contextmenu', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.oncontextmenu();
    }
}
scwin.rightClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireClick(el);
}
scwin.checkEl = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id)) {
        return false;
    }
    return true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 0. gridView속성의 contextMenu='false로 설정한다.
    //Set the contextMenu = 'false' of the gridView property.
    // verify step 0. gridView속성의 contextMenu='false로 설정된다.
    //0. The contextMenu of the gridView property is set to 'false'.
    // Test step 1. 샘플 실행 후 gridView에서 마우스 우클릭을 실행한다.
    //1. After executing the sample, right-click in gridView.
    WebSquare.wUnit.addCommand("set", "scwin.rightClick($p.id+'gv1_cell_4_1')");
    // verify step 1. contextMenu가 보여지지 않는다.(정상)(이전에는 false로 설정해도 보여졌음)
    //1. The contextMenu is not shown (normal)
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('gv1_contextMenu_list')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
